// components/ScriptReader.js

import React, { useState, useCallback } from 'react';
import { FileText, UploadCloud, Eye, EyeOff, Download, Trash2 } from 'lucide-react';
import * as mammoth from "mammoth";

const ScriptReader = () => {
  const [scriptContent, setScriptContent] = useState('');
  const [scriptText, setScriptText] = useState(''); // Plain text version for search
  const [fileName, setFileName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showRawText, setShowRawText] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const handleFileUpload = useCallback(async (event) => {
    const file = event.target.files[0];

    if (file) {
      setIsLoading(true);
      setFileName(file.name);
      
      try {
        if (file.type === 'text/plain') {
          const reader = new FileReader();
          reader.onload = (e) => {
            const text = e.target.result;
            // Convert plain text to HTML with line breaks
            const htmlContent = text.replace(/\n/g, '<br>');
            setScriptContent(htmlContent);
            setScriptText(text);
            localStorage.setItem('melodicJustice_script_html', htmlContent);
            localStorage.setItem('melodicJustice_script_text', text);
            localStorage.setItem('melodicJustice_script_filename', file.name);
          };
          reader.readAsText(file);
        } else if (
          file.type === 'application/msword' || 
          file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
        ) {
          const arrayBuffer = await file.arrayBuffer();
          
          // Extract HTML with formatting
          const htmlResult = await mammoth.convertToHtml({ 
            arrayBuffer: arrayBuffer 
          }, {
            // Custom style mapping for better formatting
            styleMap: [
              "p[style-name='Title'] => h1:fresh",
              "p[style-name='Heading 1'] => h1:fresh",
              "p[style-name='Heading 2'] => h2:fresh",
              "p[style-name='Character Name'] => p.character:fresh",
              "p[style-name='Scene Heading'] => p.scene-heading:fresh",
              "p[style-name='Action'] => p.action:fresh",
              "p[style-name='Dialogue'] => p.dialogue:fresh",
              "p[style-name='Parenthetical'] => p.parenthetical:fresh",
              "p[style-name='Transition'] => p.transition:fresh",
              // Preserve center alignment
              "p[style-name='Center'] => p.center:fresh"
            ]
          });
          
          // Extract plain text for search functionality
          const textResult = await mammoth.extractRawText({ arrayBuffer: arrayBuffer });
          
          setScriptContent(htmlResult.value);
          setScriptText(textResult.value);
          localStorage.setItem('melodicJustice_script_html', htmlResult.value);
          localStorage.setItem('melodicJustice_script_text', textResult.value);
          localStorage.setItem('melodicJustice_script_filename', file.name);

          // Log any conversion messages/warnings
          if (htmlResult.messages.length > 0) {
            console.log('Conversion messages:', htmlResult.messages);
          }
        } else {
          alert('Please upload a plain text (.txt), .doc, or .docx file.');
        }
      } catch (error) {
        console.error("Error processing file:", error);
        alert(`Error reading file: ${error.message}`);
      } finally {
        setIsLoading(false);
      }
    }
  }, []);

  // Load saved script on component mount
  React.useEffect(() => {
    const savedScriptHtml = localStorage.getItem('melodicJustice_script_html');
    const savedScriptText = localStorage.getItem('melodicJustice_script_text');
    const savedFileName = localStorage.getItem('melodicJustice_script_filename');
    
    if (savedScriptHtml && savedScriptText) {
      setScriptContent(savedScriptHtml);
      setScriptText(savedScriptText);
      setFileName(savedFileName || 'Saved Script');
    }
  }, []);

  // Clear script
  const clearScript = () => {
    if (window.confirm('Are you sure you want to clear the current script?')) {
      setScriptContent('');
      setScriptText('');
      setFileName('');
      setSearchTerm('');
      localStorage.removeItem('melodicJustice_script_html');
      localStorage.removeItem('melodicJustice_script_text');
      localStorage.removeItem('melodicJustice_script_filename');
    }
  };

  // Download script as HTML
  const downloadScript = () => {
    if (!scriptContent) return;
    
    const htmlContent = `
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>${fileName || 'Script'}</title>
    <style>
        body { 
            font-family: 'Courier New', monospace; 
            line-height: 1.6; 
            max-width: 800px; 
            margin: 0 auto; 
            padding: 40px 20px;
            background: white;
            color: black;
        }
        .character { font-weight: bold; text-align: center; margin: 20px 0 10px 0; }
        .scene-heading { font-weight: bold; text-transform: uppercase; margin: 20px 0; }
        .action { margin: 10px 0; }
        .dialogue { margin: 0 60px; }
        .parenthetical { margin: 0 80px; font-style: italic; }
        .transition { text-align: right; font-weight: bold; margin: 20px 0; }
        .center { text-align: center; }
    </style>
</head>
<body>
    ${scriptContent}
</body>
</html>`;
    
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fileName.replace(/\.[^/.]+$/, '')}_formatted.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // Highlight search terms in content
  const highlightSearchTerm = (content, searchTerm) => {
    if (!searchTerm.trim()) return content;
    
    const regex = new RegExp(`(${searchTerm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    return content.replace(regex, '<mark style="background-color: yellow; color: black;">$1</mark>');
  };

  const displayContent = searchTerm ? 
    highlightSearchTerm(scriptContent, searchTerm) : 
    scriptContent;

  return (
    <div className="rounded-lg p-6 fade-in shadow-xl" style={{ backgroundColor: '#2f2a2f' }}>
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <FileText className="w-8 h-8 text-cyan-400" />
          <div>
            <h2 className="text-2xl font-bold text-white">Script Reader</h2>
            <p className="text-gray-400">Upload and view your script with formatting preserved</p>
          </div>
        </div>
        
        <div className="flex items-center gap-3 flex-wrap">
          {scriptContent && (
            <>
              <button
                onClick={() => setShowRawText(!showRawText)}
                className="px-3 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg flex items-center gap-2 transition-all"
                title={showRawText ? "Show formatted view" : "Show raw text"}
              >
                {showRawText ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                {showRawText ? "Format" : "Raw"}
              </button>
              
              <button
                onClick={downloadScript}
                className="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg flex items-center gap-2 transition-all"
                title="Download as HTML"
              >
                <Download className="w-4 h-4" />
                Download
              </button>
              
              <button
                onClick={clearScript}
                className="px-3 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg flex items-center gap-2 transition-all"
                title="Clear script"
              >
                <Trash2 className="w-4 h-4" />
                Clear
              </button>
            </>
          )}
          
          <label className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600 text-white rounded-lg transition-all shadow-md hover:shadow-lg">
            <UploadCloud className="w-5 h-5" />
            {isLoading ? 'Processing...' : 'Upload Script'}
            <input
              type="file"
              accept=".txt,.doc,.docx"
              onChange={handleFileUpload}
              className="hidden"
              disabled={isLoading}
            />
          </label>
        </div>
      </div>

      {/* Search Bar */}
      {scriptContent && (
        <div className="mb-6">
          <div className="relative max-w-md">
            <input
              type="text"
              placeholder="Search in script..."
              className="w-full px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white focus:ring-2 focus:ring-cyan-500 focus:outline-none"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            {searchTerm && (
              <button
                onClick={() => setSearchTerm('')}
                className="absolute right-2 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-white"
              >
                ×
              </button>
            )}
          </div>
        </div>
      )}

      {/* Script Content */}
      <div className="bg-white rounded-lg shadow-inner" style={{ minHeight: '70vh' }}>
        {isLoading ? (
          <div className="flex items-center justify-center h-64">
            <div className="text-gray-600">Processing file...</div>
          </div>
        ) : scriptContent ? (
          <div 
            className="p-8 overflow-y-auto custom-scrollbar"
            style={{ 
              maxHeight: '70vh',
              fontFamily: showRawText ? 'Monaco, "Courier New", monospace' : '"Times New Roman", serif',
              fontSize: '16px',
              lineHeight: '1.6',
              color: 'black'
            }}
          >
            {showRawText ? (
              <pre className="whitespace-pre-wrap">{scriptText}</pre>
            ) : (
              <div 
                dangerouslySetInnerHTML={{ __html: displayContent }}
                style={{
                  // Custom CSS for script formatting
                  '--character-style': 'font-weight: bold; text-align: center; margin: 20px 0 10px 0; text-transform: uppercase;',
                  '--scene-heading-style': 'font-weight: bold; text-transform: uppercase; margin: 20px 0;',
                  '--action-style': 'margin: 10px 0;',
                  '--dialogue-style': 'margin: 0 60px;',
                  '--parenthetical-style': 'margin: 0 80px; font-style: italic;',
                  '--transition-style': 'text-align: right; font-weight: bold; margin: 20px 0;',
                  '--center-style': 'text-align: center;'
                }}
                className="script-content"
              />
            )}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-64 text-gray-500">
            <FileText className="w-16 h-16 mb-4 opacity-50" />
            <p className="text-lg mb-2">No script loaded</p>
            <p className="text-sm">Upload a .txt, .doc, or .docx file to begin</p>
          </div>
        )}
      </div>

      {/* File Info */}
      {fileName && (
        <div className="mt-4 flex items-center justify-between text-sm text-gray-400">
          <div>
            <span className="font-medium">File:</span> {fileName}
          </div>
          {scriptText && (
            <div>
              <span className="font-medium">Characters:</span> {scriptText.length.toLocaleString()}
              <span className="ml-4 font-medium">Words:</span> {scriptText.split(/\s+/).filter(word => word.length > 0).length.toLocaleString()}
            </div>
          )}
        </div>
      )}

      {/* Custom CSS for script formatting */}
      <style jsx>{`
        .script-content .character {
          font-weight: bold;
          text-align: center;
          margin: 20px 0 10px 0;
          text-transform: uppercase;
        }
        .script-content .scene-heading {
          font-weight: bold;
          text-transform: uppercase;
          margin: 20px 0;
        }
        .script-content .action {
          margin: 10px 0;
        }
        .script-content .dialogue {
          margin: 0 60px;
        }
        .script-content .parenthetical {
          margin: 0 80px;
          font-style: italic;
        }
        .script-content .transition {
          text-align: right;
          font-weight: bold;
          margin: 20px 0;
        }
        .script-content .center {
          text-align: center;
        }
        .script-content p {
          margin: 10px 0;
        }
        .script-content h1, .script-content h2 {
          font-weight: bold;
          text-align: center;
          margin: 30px 0 20px 0;
        }
        .script-content h1 {
          font-size: 1.5em;
          text-transform: uppercase;
        }
        .script-content h2 {
          font-size: 1.2em;
        }
      `}</style>
    </div>
  );
};

export default ScriptReader;
